 ids=run(['docker','ps','-q','--filter','label=com.docker.compose.project=redhouse-parcial2']).split();assert ids
 inspected=json.loads(run(['docker','inspect',*ids]));containers={v['Config']['Labels']['com.docker.compose.service']:{'id':v['Id'],'image':v['Image'],'health':v['State'].get('Health',{}).get('Status')} for v in inspected}
