 def generate(label,sources):
  source=STAGE/label/'source';directory=STAGE/label/'generated';(directory/'apps').mkdir(parents=True);(directory/'web.json').write_text('{}');source.mkdir(parents=True)
  shutil.copyfile(ROOT/'compose.yaml',source/'compose.yaml')
