 REPORT.update(phase='preflight_passed',candidate_syntax_passed=True,candidate_sha256=digest(candidate),active_sha256=digest(active),source_hashes={name:hashlib.sha256(base64.b64decode(encoded)).hexdigest() for name,encoded in PAYLOAD.items()},backup_directory=str(STAGE/'backup'),container_temporary_config=remote_temp)
